    receiveMercadoPagoWebhook: {
        parameters: {
            query?: {
                /**
                 * @description Identificador del pago, repetido en la dirección; entra en el cálculo de la firma.
                 * @example 1234567890
                 */
                "data.id"?: string;
            };
            header: {
                /**
                 * @description Identificador de la solicitud que genera Mercado Pago; entra en el cálculo de la firma.
                 * @example 4a1b9d7e-6f3c-4b0a-8c52-9d1e7f2a3b4c
                 */
                "x-request-id": string;
                /**
                 * @description Firma de la notificación, con el formato `ts=<marca de tiempo>,v1=<hash>`.
                 * @example ts=1742505638683,v1=ced36ab6d33566bb1e16c125819b8d840d6b8ef136b0b9127c76064466f5229b
                 */
                "x-signature": string;
            };
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["MercadoPagoWebhookEvent"];
            };
        };
        responses: {
            /** @description Notificación registrada. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description La firma no es válida. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "type": "invalid_signature",
                     *       "title": "Firma inválida",
                     *       "status": 401,
                     *       "detail": "La firma de la notificación no coincide."
                     *     }
                     */
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            500: components["responses"]["ServerError"];
        };
    };
